// Gate + shape. This is deliberately ALL this workflow does itself — the
// change/render heavy lifting is delegated to the engine
// (workflow.import-regen-post.json) in the next node.
const j = $('Patch request').first().json;
const body = j.body || {};
const expected = $env.RENDER_WEBHOOK_TOKEN || '';
if (expected) {
  const got = (j.headers && j.headers['x-render-token']) || body.token || '';
  if (got !== expected) throw new Error('invalid or missing render token');
}
if (!body.movieId) throw new Error('body.movieId is required (the ?movieId= param on the IG grid)');
let dialogue = String(body.dialogue || '').trim();
if (!dialogue) throw new Error('body.dialogue is required');
// YakYak convention: dialogue must not end in a period ("!" / "?" are fine)
dialogue = dialogue.replace(/\.+$/, '');
const sceneNumber = Number(body.sceneNumber || 1);
if (!Number.isInteger(sceneNumber) || sceneNumber < 1) throw new Error('body.sceneNumber must be a positive integer');
return [{ json: { movieId: body.movieId, dialogue, sceneNumber, chatId: body.chatId || '' } }];

// Same delivery as workflow.render-to-telegram.json: sendVideo fetches the mp4
// by URL so it arrives playable (≤ ~20 MB); fall back to a link message.
const url = $json.url;
if (!url) throw new Error('engine returned no movie URL: ' + JSON.stringify($json).slice(0, 200));
const v = $('Validate').first().json;
const chatId = v.chatId || $env.TELEGRAM_CHAT_ID;
if (!chatId) throw new Error('no chat id — set TELEGRAM_CHAT_ID on the instance or pass chatId in the body');
const bot = $env.TELEGRAM_BOT_TOKEN;
if (!bot) throw new Error('TELEGRAM_BOT_TOKEN env var is not set');
const changed = Number($json.changed || 0);
const caption = `\u{1F3AC} Scene ${v.sceneNumber} dialogue ${changed ? 'updated' : 'unchanged (no-op — same line as before)'}:\n\u{201C}${v.dialogue}\u{201D}\n${url}`;
const tg = (method, body) => this.helpers.httpRequest({
  method: 'POST', url: `https://api.telegram.org/bot${bot}/${method}`,
  body, json: true,
});
let delivered = 'video';
try {
  await tg('sendVideo', { chat_id: chatId, video: url, caption });
} catch (e) {
  await tg('sendMessage', { chat_id: chatId, text: caption });
  delivered = 'link';
}
return [{ json: { url, movieId: v.movieId, sceneNumber: v.sceneNumber, dialogue: v.dialogue, changed, delivered } }];
